"""Derive review rows from stored HTTP + browser evidence, without requests."""
import hashlib, json, pathlib
p=pathlib.Path('outputs/seo-p1-20261104/production');out=pathlib.Path('docs/seo-p1-20261104')
a=json.loads((p/'audit.json').read_text(encoding='utf-8'));browser={r['url']:r for r in json.loads((p/'browser.json').read_text(encoding='utf-8'))}
rows=[]
for r in a['targets']:
 d=browser[r['url']];desc=d.get('description');text=r['mainText']
 state='not-applicable' if '/book/' not in r['url'] else 'missing' if desc and ('not available yet' in desc or 'nog geen geverifieerde' in desc) else 'temporary-source-failure' if desc and ('tijdelijk' in desc or 'could not load' in desc) else 'visible' if desc else 'not-observed'
 missing='geverifieerde Nederlandse editie beschikbaar' in text or 'verified English edition is not available' in text
 row={k:r[k] for k in ['url','cohorts','status','finalUrl','canonical','robots','headValid','mainWords','inSitemap','sameLanguageInlinks','observedHomePath','sha256','ttfbMs','totalMs']}
 row.update(title=d.get('h1'),editionState='verified-language-edition-missing' if missing else 'no-missing-edition-notice',descriptionState=state,descriptionSources=d.get('sourceLinks',[]),browserCanonical=d['canonical'],classification='gericht te verbeteren' if missing or state in ['missing','temporary-source-failure'] else 'waardevol indexeerbaar',browserImages=d['images'])
 rows.append(row)
report={'checkedAt':a['checkedAt'],'productionSha':a['productionSha'],'deployment':'dpl_F6j6cQ9TTBm3RUnXxfEJDeDPXDwN','boundaries':a['boundaries'],'historicalSourceHashes':a['sourceHashes'],'evidenceFiles':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in [p/'audit.json',p/'browser.json']},'rows':rows}
(out/'cohorts.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# Vaste cohorten: productiecontrole 4 november 2026','',f"Productie `{a['productionSha']}`. 42 verschillende URLs (30 + 12; geen overlap), 158 begrensde publieke GET-documenten, twee gelijktijdige requests en 42 browser-DOM-controles. De GET-crawl gebruikte geen cookies. De browser had een bestaande sessie en is uitsluitend read-only gebruikt; geen persoonlijke gegevens opgenomen.",'', 'Alle 42: HTTP 200, één juiste canonical in geldige oorspronkelijke head, index/follow en opgenomen in de sitemap. Dit bewijst geen actuele Google-indexstatus. Alle twaalf prioriteiten hebben een waargenomen publiek pad. Voor 12/30 oude uitsluitingen is een inlink/pad gevonden; voor 18 niet binnen deze crawl. Geen volledige orphan-claim.','', 'Twintig boeken in het uitsluitingscohort: 5 zichtbare beschrijvingen, 11 ontbrekendmeldingen en 4 tijdelijke bronfouten. Elf missen een geverifieerde editie in de gevraagde taal (7 NL/4 EN). Deze tellingen overlappen. De vijf boeken in het prioriteitscohort hebben alle een zichtbare beschrijving. Tijdelijke fouten zijn geen bewijs van ontbrekende broninhoud.','', '| URL | Beschrijving / editie | Geobserveerd publiek pad | Categorie |','|---|---|---|---|']
for r in rows:
 path=' → '.join(x.replace('https://lumisco.re','') for x in r['observedHomePath']) if r['observedHomePath'] else 'Niet waargenomen'
 lines.append(f"| {r['url'].replace('https://lumisco.re','')} | {r['descriptionState']}; {r['editionState']} | {path} | {r['classification']} |")
lines+=['', '## Vervolg en grenzen','Gericht te verbeteren betekent een afzonderlijk editie-/inhoudsdossier of onderzoek naar een tijdelijke bronfout; geen automatische noindex. Alle vaste 42 zijn gewone content-URLs. Bedoelde noindex-varianten (zoeken en filter/sortvarianten van Browse) staan afzonderlijk in het pagineringsbewijs. Een niet geladen lazy afbeelding in deze controle is geen bewezen kapotte cover.','', 'De JSON bevat letterlijke inlink-ankers/hrefs, bronnen, canonicals, robots, controles en timing. Een navigatiepad normaliseert uitsluitend de returnTo-query op een boeklink; de letterlijke href blijft ernaast bewaard. Geen claim dat een crawler alle paden werkelijk heeft bezocht.','', 'De 30 uitsluitingen komen uit de oude GSC-export (stand 23 oktober; audit 30 oktober). De twaalf prioriteiten zijn de bestaande herstelcohort van 3 november. Ontbrekende exportregels zijn onbekend, niet nul. Geen nieuwe GSC-inspectie, aanvraag of sitemapinzending.','', 'De sitemap is opnieuw gelezen met een passende XML-limiet van 15MB nadat de bestaande HTML-checker zijn 5MB-cap bereikte. Bestaande HTML/checkpoints zijn hergebruikt. De 100 extra hubpagina’s vormen één begrensde laag, geen volledige sitecrawl.','', 'De tien bestaande redactionele dossiers in `docs/product-explanation-social-20261104/book-selection.json` blijven de inhoudelijke prioriteitslijst. PR74/75 en de vier goedgekeurde Suzanne-coverbindings zijn al gepubliceerd; geen concurrerend Suzanne-pakket.','', 'Geen productiegegevens, scores, rangschikking of editievoorwaarden gewijzigd. Oude Google-status, huidige HTTP-response en uiteindelijke browser-DOM zijn afzonderlijke bewijzen.']
(out/'COHORTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
pages=[]
for d in a['documents']:
 if '/browse' in d['url'] and d['url'].split('/browse')[1] in ['', '?page=2','?page=3','?page=2&pageSize=16&sort=highest']:
  pages.append({k:d[k] for k in ['url','status','html','sha256','ttfbMs','totalMs']}|{'bookLinks':[x for x in d['links'] if '/book/' in x['url']],'paginationLinks':[x for x in d['links'] if x['rel'] in ['next','prev']]})
(out/'pagination-before.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'rows':len(rows),'baselines':len(pages)}))
